pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 depositAmt, uint256 collectAmt) internal {
        depositAmt = bound(depositAmt, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(depositAmt > 0);
        vm.assume(collectAmt > depositAmt);
        try c.SetMinSum(0) {} catch { return; }
        try c.Deposit{value: depositAmt}() {} catch { return; }
        uint256 balBefore;
        try c.balances(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint ethBefore = address(c).balance;
        bool reverted;
        try c.Collect(collectAmt) { reverted = false; } catch { reverted = true; }
        assertTrue(!reverted && c.balances(address(this)) == balBefore && address(c).balance == ethBefore);
    }

    function testFuzz_run(uint256 depositAmt, uint256 collectAmt) public {
        _run(depositAmt, collectAmt);
    }

    receive() external payable {}
}
